    pub fn m3_rank(&self,r:&crate::repository::M3RankRequest)->Result<serde_json::Value,String> {
        if self.guarded_epoch!=Some(18) {return Err("ranking unavailable".into());}
        let mut conn=self.conn.lock().map_err(|_|"ranking unavailable")?;
        let tx=conn.transaction_with_behavior(TransactionBehavior::Deferred).map_err(|_|"ranking unavailable")?;
        self.guarded_schema_snapshot(&tx).map_err(|_|"ranking unavailable")?;
        let database:String=tx.query_row("SELECT value FROM fm_meta WHERE key='database_id'",[],|row|row.get(0)).map_err(|_|"ranking unavailable")?;
        let mut budget=crate::repository::ResetFenceBudget::install(&tx);
        let view=crate::repository::owner_custody::verified_or_direct_custody_view(&tx,&database,&r.account_id,&r.owner,&r.owner,&mut budget).map_err(|_|"ranking unavailable")?;
        let result=crate::repository::m3_rank::rank_in_tx(&tx,r,&view,&mut budget).map_err(|_|"ranking unavailable");
        drop(view);drop(budget);let result=result?;tx.commit().map_err(|_|"ranking unavailable")?;Ok(result)
    }

