    fn account_owner_custody<'a,'db>(tx:&'a rusqlite::Transaction<'db>,owner:&str,account:&str,budget:&mut crate::repository::ResetFenceBudget)->Result<Option<crate::repository::owner_custody::VerifiedCustodyView<'a,'db>>,String> {
        if [owner,account].iter().any(|v|v.is_empty() || v.trim()!=*v || v.len()>512) {return Err("review scope unavailable".into());}
        crate::repository::require_guarded_epoch(tx).map_err(|_|"review custody unavailable")?;
        let database:String=tx.query_row("SELECT value FROM fm_meta WHERE key='database_id'",[],|r|r.get(0)).map_err(|_|"review custody unavailable")?;
        let keys=crate::repository::owner_custody::account_custody_keys(tx,&database,account,budget).map_err(|_|"review custody unavailable")?;
        if keys.is_empty() {
            let epoch:i64=tx.query_row("PRAGMA user_version",[],|r|r.get(0)).map_err(|_|"review custody unavailable")?;
            if epoch==18 {return Ok(Some(crate::repository::owner_custody::verified_or_direct_custody_view(tx,&database,account,owner,owner,budget).map_err(|_|"review custody unavailable")?));}
            return Ok(None);
        }
        Ok(Some(crate::repository::owner_custody::verified_custody_view(tx,&database,account,owner,owner,budget).map_err(|_|"review custody unavailable")?))
    }

    fn explicit_review_custody<'a,'db>(tx:&'a rusqlite::Transaction<'db>,s:&ExplicitAddReviewSelector,budget:&mut crate::repository::ResetFenceBudget)->Result<Option<crate::repository::owner_custody::VerifiedCustodyView<'a,'db>>,String> {
        if s.version!=1 || [&s.owner,&s.workspace_id,&s.account_id,&s.candidate_id].iter().any(|v|v.is_empty() || v.trim()!=v.as_str() || v.len()>512) {return Err("review scope unavailable".into());}
        Self::account_owner_custody(tx,&s.owner,&s.account_id,budget)
    }

    fn explicit_add_review_current(tx:&rusqlite::Transaction<'_>, selector:&ExplicitAddReviewSelector)->Result<crate::repository::explicit_add::ExplicitAddReviewBinding,String> {
        if selector.version!=1 || [&selector.owner,&selector.workspace_id,&selector.account_id,&selector.candidate_id].iter().any(|v|v.is_empty() || v.trim()!=v.as_str() || v.len()>512) {return Err("explicit Add review scope unavailable".into());}
        crate::repository::require_guarded_epoch(tx).map_err(|e|e.to_string())?;
        crate::repository::require_policy_projection(tx,&selector.account_id,&selector.workspace_id,Some(&selector.policy_projection)).map_err(|e|e.to_string())?;
        let association=crate::repository::explicit_add::explicit_add_erase_association(tx,&selector.owner,&selector.workspace_id,&selector.account_id,&selector.candidate_id).map_err(|e|e.to_string())?;
        let mode=explicit_add::validate_explicit_add_original(tx,&selector.owner,&selector.workspace_id,&selector.account_id,&selector.candidate_id,&association.original_request_key,&association.original_input_sha256)?;
        if mode!=ExplicitAddMode::ReviewOnly || association.legacy_status!="pending" || association.accepted_curated_id.is_some() {return Err("explicit Add review unavailable".into());}
        crate::repository::explicit_add::explicit_add_review_binding(tx,&selector.owner,&selector.workspace_id,&selector.candidate_id).map_err(|e|e.to_string())
    }

    pub fn explicit_add_review_preview(&self, selector:&ExplicitAddReviewSelector)->Result<serde_json::Value,String> {
        let mut conn=self.conn.lock().map_err(|_|"explicit Add review unavailable".to_string())?;
        let tx=conn.transaction_with_behavior(TransactionBehavior::Deferred).map_err(|e|e.to_string())?;
        let mut budget=crate::repository::ResetFenceBudget::install(&tx);
        if let Some(view)=Self::explicit_review_custody(&tx,selector,&mut budget)? {
            let result=explicit_add::review_preview_custody(&tx,selector,&view,&mut budget)?;drop(view);drop(budget);tx.commit().map_err(|e|e.to_string())?;return Ok(result);
        }
        drop(budget);
        let current=Self::explicit_add_review_current(&tx,selector)?;
        let result=serde_json::json!({"state":"preview","candidate_id":selector.candidate_id,"proposal":current.proposal,"expected_revision":current.expected_revision,"binding_sha256":current.binding_sha256});
        tx.commit().map_err(|e|e.to_string())?;Ok(result)
    }

    fn explicit_add_review_identity(tx:&rusqlite::Transaction<'_>,request:&ExplicitAddReviewApplyRequest)->Result<(),String> {
        let scope=&request.selector;
        if scope.version!=1 || [&scope.owner,&scope.workspace_id,&scope.account_id,&scope.candidate_id,&request.review_key].iter().any(|v|v.is_empty() || v.trim()!=v.as_str() || v.len()>512) || !matches!(request.action.as_str(),"accept"|"reject") || request.expected_revision<1 || request.expected_binding.len()!=64 || !request.expected_binding.bytes().all(|b|b.is_ascii_digit()||(b'a'..=b'f').contains(&b)) {return Err("explicit Add review identity unavailable".into());}
        crate::repository::require_guarded_epoch(tx).map_err(|e|e.to_string())?;Ok(())
    }
    fn explicit_add_review_not_applied(request:&ExplicitAddReviewApplyRequest,reason:&str)->serde_json::Value {
        serde_json::json!({"state":"not_applied","candidate_id":request.selector.candidate_id,"expected_revision":request.expected_revision,"expected_binding":request.expected_binding,"review_key":request.review_key,"action":request.action,"reason":reason})
    }
    fn explicit_add_review_original_in(tx:&rusqlite::Transaction<'_>,request:&ExplicitAddReviewApplyRequest)->Result<Option<serde_json::Value>,String> {
        let scope=&request.selector;Self::explicit_add_review_identity(tx,request)?;
        crate::repository::require_policy_projection(tx,&scope.account_id,&scope.workspace_id,Some(&scope.policy_projection)).map_err(|e|e.to_string())?;
        if let Some(marker)=crate::repository::explicit_add::read_explicit_add_terminal(tx,&scope.owner,&scope.workspace_id,&scope.account_id,&scope.candidate_id).map_err(|e|e.to_string())? {
            let key=crate::repository::explicit_add::explicit_add_review_key_sha256(&scope.account_id,&scope.workspace_id,&scope.candidate_id,&request.review_key).map_err(|e|e.to_string())?;
            if marker.review_key_sha256.as_deref()!=Some(key.as_str()) || marker.review_action.as_deref()!=Some(request.action.as_str()) || marker.review_revision!=Some(request.expected_revision) || marker.review_binding.as_deref()!=Some(request.expected_binding.as_str()) {return Err("explicit Add review identity conflict".into());}
            return Ok(Some(serde_json::json!({"state":"terminal_erased","candidate_id":scope.candidate_id})));
        }
        let receipt=crate::repository::explicit_add::read_explicit_add_review_receipt(tx,&scope.owner,&scope.workspace_id,&scope.account_id,&scope.candidate_id).map_err(|e|e.to_string())?;
        let Some(receipt)=receipt else {return Ok(None)};
        if receipt.review_key!=request.review_key || receipt.expected_revision!=request.expected_revision || receipt.expected_binding!=request.expected_binding || receipt.action!=request.action {return Err("explicit Add review identity conflict".into());}
        Ok(Some(serde_json::json!({"state":if receipt.action=="accept" {"applied"} else {"rejected"},"candidate_id":scope.candidate_id,"curated_id":receipt.curated_id})))
    }

    pub fn explicit_add_review_original(&self,selector:&ExplicitAddReviewSelector)->Result<serde_json::Value,String> {
        if selector.version!=1 || [&selector.owner,&selector.workspace_id,&selector.account_id,&selector.candidate_id].iter().any(|v|v.is_empty() || v.trim()!=v.as_str() || v.len()>512) {return Err("explicit Add review scope unavailable".into());}
        let mut conn=self.conn.lock().map_err(|_|"explicit Add review unavailable".to_string())?;
        let tx=conn.transaction_with_behavior(TransactionBehavior::Deferred).map_err(|e|e.to_string())?;
        let mut budget=crate::repository::ResetFenceBudget::install(&tx);
        if let Some(view)=Self::explicit_review_custody(&tx,selector,&mut budget)? {
            let result=explicit_add::review_original_custody(&tx,selector,&view,&mut budget)?;drop(view);drop(budget);tx.commit().map_err(|e|e.to_string())?;return Ok(result);
        }
        drop(budget);
        crate::repository::require_guarded_epoch(&tx).map_err(|e|e.to_string())?;
        crate::repository::require_policy_projection(&tx,&selector.account_id,&selector.workspace_id,Some(&selector.policy_projection)).map_err(|e|e.to_string())?;
        if crate::repository::explicit_add::read_explicit_add_terminal(&tx,&selector.owner,&selector.workspace_id,&selector.account_id,&selector.candidate_id).map_err(|e|e.to_string())?.is_some() {
            tx.commit().map_err(|e|e.to_string())?;return Ok(serde_json::json!({"state":"terminal_erased","candidate_id":selector.candidate_id}));
        }
        let receipt=crate::repository::explicit_add::read_explicit_add_review_receipt(&tx,&selector.owner,&selector.workspace_id,&selector.account_id,&selector.candidate_id).map_err(|e|e.to_string())?;
        let result=match receipt {None=>serde_json::json!({"state":"absent"}),Some(r)=>serde_json::json!({"state":"found","original":{"candidate_id":r.candidate,"expected_revision":r.expected_revision,"expected_binding":r.expected_binding,"review_key":r.review_key,"action":r.action},"receipt":{"state":if r.action=="accept" {"applied"} else {"rejected"},"candidate_id":selector.candidate_id,"curated_id":r.curated_id}})};
        tx.commit().map_err(|e|e.to_string())?;Ok(result)
    }

    pub fn explicit_add_missing_page(&self,request:&ExplicitAddMissingPageRequest,terminal:bool)->Result<serde_json::Value,String> {
        if request.version!=1 || [&request.owner,&request.workspace_id,&request.account_id].iter().any(|v|v.is_empty() || v.trim()!=v.as_str() || v.len()>512) {return Err("explicit Add page scope unavailable".into());}
        let mut conn=self.conn.lock().map_err(|_|"explicit Add page unavailable".to_string())?;
        let tx=conn.transaction_with_behavior(TransactionBehavior::Deferred).map_err(|e|e.to_string())?;
        crate::repository::require_guarded_epoch(&tx).map_err(|e|e.to_string())?;
        crate::repository::require_policy_projection(&tx,&request.account_id,&request.workspace_id,Some(&request.policy_projection)).map_err(|e|e.to_string())?;
        let mut budget=crate::repository::ResetFenceBudget::install(&tx);
        if let Some(view)=Self::account_owner_custody(&tx,&request.owner,&request.account_id,&mut budget)? {
            let value=if terminal {crate::repository::explicit_add::explicit_add_missing_terminal_page_custody(&tx,&request.workspace_id,&request.account_id,request.after.as_deref(),request.limit,&view,&mut budget)} else {crate::repository::explicit_add::explicit_add_missing_original_page_custody(&tx,&request.workspace_id,&request.account_id,request.after.as_deref(),request.limit,&view,&mut budget)}.map_err(|e|e.to_string())?;
            drop(view);drop(budget);tx.commit().map_err(|e|e.to_string())?;return Ok(value);
        }
        drop(budget);
        let value=if terminal {crate::repository::explicit_add::explicit_add_missing_terminal_page(&tx,&request.owner,&request.workspace_id,&request.account_id,request.after.as_deref(),request.limit)} else {crate::repository::explicit_add::explicit_add_missing_original_page(&tx,&request.owner,&request.workspace_id,&request.account_id,request.after.as_deref(),request.limit)}.map_err(|e|e.to_string())?;
        tx.commit().map_err(|e|e.to_string())?;Ok(value)
    }

